      {
        "parameters": {
          "jsCode": "\nconst env = $('ME_Validate_Dispatcher_Result').first().json;\nconst step = env.step;\nconst inputs = step.inputs || {};\nif (!inputs.task_id && !inputs.title_match) {\n  return [{ json: { _error: true, error_code: 'MISSING_REQUIRED_FIELDS', error_message: 'Task update requires task_id or title_match.', missing_fields: ['task_id_or_title_match'] } }];\n}\nconst mutable = ['title','description','priority','due_date','due_at','status'];\nconst patch = {};\nfor (const k of mutable) {\n  if (inputs[k] !== undefined && inputs[k] !== null) patch[k] = inputs[k];\n}\nif (Object.keys(patch).length === 0) {\n  return [{ json: { _error: true, error_code: 'MISSING_REQUIRED_FIELDS', error_message: 'Task update requires at least one mutable field.', missing_fields: ['patch'] } }];\n}\nreturn [{ json: {\n  status_kind: 'success',\n  result_type: 'module_result',\n  execution_context_id: env.execution_context_id,\n  thread_id: env.thread_id,\n  tenant_id: env.tenant_id,\n  module_result: {\n    module_name: 'task_module',\n    step_id: step.step_id,\n    result_type: 'execution',\n    status: 'success',\n    summary: 'Task update request prepared successfully.',\n    observations: [],\n    proposals: [],\n    actions_executed: [{\n      action: 'update_task',\n      details: { task_id: inputs.task_id || null, title_match: inputs.title_match || null, patch: patch }\n    }],\n    artifacts: [],\n    confidence: 1.0,\n    needs_followup: false,\n    followup_requests: []\n  },\n  module_execution_started: true,\n  domain_writes_performed: false,\n  response_generation_allowed: false\n}}];\n"
        },
